import { createHash } from "node:crypto";
let vaultDb;
function vault(){if(vaultDb)return vaultDb;const path=Bun.env.VAULT_PATH||"/data/user-profiles.sqlite";vaultDb=new Database(path,{create:true});vaultDb.exec("PRAGMA journal_mode=WAL; PRAGMA busy_timeout=3000; CREATE TABLE IF NOT EXISTS backups (id TEXT PRIMARY KEY, iv TEXT NOT NULL, ciphertext TEXT NOT NULL, revision INTEGER NOT NULL, saved_at TEXT NOT NULL)");return vaultDb}
const vaultNoCache={'cache-control':'no-store','x-content-type-options':'nosniff'};
async function vaultRequest(req){let token=req.headers.get('authorization')||'';if(!token.startsWith('Bearer '))return Response.json({error:'Ключ восстановления не указан'},{status:401,headers:vaultNoCache});token=token.slice(7);if(!/^[A-Za-z0-9_-]{43}$/.test(token))return Response.json({error:'Неверный формат ключа восстановления'},{status:401,headers:vaultNoCache});const id=createHash('sha256').update(token).digest('hex'),db=vault();if(req.method==='GET'){const row=db.query('SELECT iv,ciphertext,revision,saved_at FROM backups WHERE id=?').get(id);return row?Response.json({iv:row.iv,ciphertext:row.ciphertext,revision:row.revision,savedAt:row.saved_at},{headers:vaultNoCache}):Response.json({error:'Резервная копия не найдена'},{status:404,headers:vaultNoCache})}if(req.method==='DELETE'){db.query('DELETE FROM backups WHERE id=?').run(id);return Response.json({deleted:true},{headers:vaultNoCache})}if(req.method!=='PUT')return Response.json({error:'Method not allowed'},{status:405,headers:vaultNoCache});const len=Number(req.headers.get('content-length')||0);if(len>350000)return Response.json({error:'Данные превышают лимит резервной копии'},{status:413,headers:vaultNoCache});const body=await req.text();if(body.length>350000)return Response.json({error:'Данные превышают лимит резервной копии'},{status:413,headers:vaultNoCache});let value;try{value=JSON.parse(body)}catch{return Response.json({error:'Неверный JSON'},{status:400,headers:vaultNoCache})}if(typeof value.iv!=='string'||!/^[A-Za-z0-9_-]{16}$/.test(value.iv)||typeof value.ciphertext!=='string'||!/^[A-Za-z0-9_-]{10,340000}$/.test(value.ciphertext))return Response.json({error:'Неверный формат зашифрованной копии'},{status:400,headers:vaultNoCache});let revision=Number(value.revision);if(!Number.isSafeInteger(revision)||revision<0||revision>Date.now()+86400000)return Response.json({error:'Неверная версия сохранения'},{status:400,headers:vaultNoCache});const old=db.query('SELECT revision FROM backups WHERE id=?').get(id);if(old&&revision<old.revision)return Response.json({error:'На сервере уже есть более свежая копия',revision:old.revision},{status:409,headers:vaultNoCache});let savedAt=new Date().toISOString();db.query('INSERT INTO backups(id,iv,ciphertext,revision,saved_at) VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET iv=excluded.iv,ciphertext=excluded.ciphertext,revision=excluded.revision,saved_at=excluded.saved_at').run(id,value.iv,value.ciphertext,revision,savedAt);return Response.json({saved:true,revision,savedAt},{headers:vaultNoCache})}
async function geocodePlace(q){let place=String(q||'').trim().slice(0,130);if(place.length<2)return [];const res=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(place)+'&count=5&language=ru&format=json',{signal:AbortSignal.timeout(7000)});if(!res.ok)throw Error('Сервис поиска городов временно недоступен');const body=await res.json();return (body.results||[]).filter(x=>x.timezone&&Number.isFinite(x.latitude)&&Number.isFinite(x.longitude)).map(x=>({name:String(x.name||''),country:String(x.country||''),admin1:String(x.admin1||''),zone:String(x.timezone),lat:x.latitude,lon:x.longitude})).slice(0,5)}

