function snapshotCurrent(date,time,offset=0){const [year,month,day,hour,minute]=strictBirth(date,time);const at=new Date(Date.UTC(year,month-1,day,hour,minute)+Math.max(-840,Math.min(840,Number(offset)||0))*60000);const phase=Astronomy.MoonPhase(at),illumination=Math.round((1-Math.cos(phase*Math.PI/180))*50);const lunar=Solar.fromYmdHms(year,month,day,hour,minute,0).getLunar(),chart=lunar.getEightChar();const labels=['Овен','Телец','Близнецы','Рак','Лев','Дева','Весы','Скорпион','Стрелец','Козерог','Водолей','Рыбы'];const sunLon=((Astronomy.SunPosition(at).elon%360)+360)%360;const label=phase<12||phase>348?'Новолуние':phase<168?'Растущая Луна':phase<192?'Полнолуние':'Убывающая Луна';return {moon:{label,illumination,phase},sun:{sign:labels[Math.floor(sunLon/30)]},bazi:{year:chart.getYear(),month:chart.getMonth(),day:chart.getDay(),hour:chart.getTime()},almanac:{yi:lunar.getDayYi().slice(0,12),ji:lunar.getDayJi().slice(0,12),tianShen:lunar.getDayTianShen(),luck:lunar.getDayTianShenLuck()}}}

function tzOffsetAt(date,time,zone){const [y,mo,d,hh,mm]=strictBirth(date,time),guess=Date.UTC(y,mo-1,d,hh,mm),f=new Intl.DateTimeFormat('en-US',{timeZone:zone,hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});let offset=0;for(let i=0;i<3;i++){let at=guess-offset*3600000,p=Object.fromEntries(f.formatToParts(new Date(at)).filter(x=>x.type!=='literal').map(x=>[x.type,+x.value]));offset=(Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute)-at)/3600000}return offset}

function vedicAntar(d){if(!d?.current?.lord)return '';const order=['Ketu','Venus','Sun','Moon','Mars','Rahu','Jupiter','Saturn','Mercury'],years={Ketu:7,Venus:20,Sun:6,Moon:10,Mars:7,Rahu:18,Jupiter:16,Saturn:19,Mercury:17};let ma=d.current.lord,end=new Date(d.current.endDate).getTime(),duration=years[ma]*365.2425*86400000,start=d.current.isPartial?end-duration:new Date(d.current.startDate).getTime();if(!Number.isFinite(start)||!Number.isFinite(end))return '';let full=d.current.isPartial?duration:end-start,now=Date.now(),elapsed=0,idx=order.indexOf(ma);if(idx<0)return '';for(let k=0;k<9;k++){const lord=order[(idx+k)%9],sub=full*years[lord]/120;if(now>=start+elapsed&&now<start+elapsed+sub)return lord;elapsed+=sub}return order[(idx+8)%9]}

